select subq_1.c4 as c0 from (select subq_0.c1 as c0, subq_0.c3 as c1, subq_0.c1 as c2, subq_0.c1 as c3, subq_0.c1 as c4, subq_0.c3 as c5, pg_catalog.txid_current_if_assigned() as c6, 6 as c7, subq_0.c3 as c8, subq_0.c2 as c9, case when true then subq_0.c2 else subq_0.c2 end as c10 from (select sample_0.id as c0, ref_0.price as c1, 15 as c2, sample_0.id as c3, ref_0.price as c4 from public.measurements_2024_q1 as sample_0 tablesample system (0.7) left join public.products as ref_0 on (sample_0.sensor_id = ref_0.id ) where cast(null as text) = cast(null as text) limit 153) as subq_0 where EXISTS ( select subq_0.c2 as c0, (select payload from public.events_login limit 1 offset 5) as c1 from public.measurements_2024_q2 as sample_1 tablesample bernoulli (0.5) where ((select numbers from public.composite_demo limit 1 offset 3) <> (select numbers from public.composite_demo limit 1 offset 5) ) and ((select score from public.active_users limit 1 offset 5) <= sample_1.id) limit 99) limit 119) as subq_1 where subq_1.c5 is NULL limit 107;
